'use strict';

const fs = require('fs');

const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let pos = 0;

const n = Number(tokens[pos++]);
const x1 = BigInt(tokens[pos++]);
const x2 = BigInt(tokens[pos++]);

const lines = [];
for (let i = 0; i < n; i++) {
  const a = BigInt(tokens[pos++]);
  const b = BigInt(tokens[pos++]);
  const y1 = a * x1 + b;
  const y2 = a * x2 + b;
  lines.push({ y1, y2 });
}

if (x1 === x2) {
  lines.sort((a, b) => a.y1 < b.y1 ? -1 : a.y1 > b.y1 ? 1 : 0);

  let answer = 0;
  for (let i = 0; i < n;) {
    let j = i + 1;
    while (j < n && lines[j].y1 === lines[i].y1) j++;
    const count = j - i;
    answer += count * (count - 1) / 2;
    i = j;
  }

  console.log(answer);
} else {
  lines.sort((a, b) => a.y1 < b.y1 ? -1 : a.y1 > b.y1 ? 1 : 0);

  const coords = lines.map(line => line.y2);
  coords.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);

  const uniqueCoords = [];
  for (const value of coords) {
    if (uniqueCoords.length === 0 || uniqueCoords[uniqueCoords.length - 1] !== value) {
      uniqueCoords.push(value);
    }
  }

  const rank = new Map();
  for (let i = 0; i < uniqueCoords.length; i++) {
    rank.set(uniqueCoords[i].toString(), i + 1);
  }

  const bit = new Int32Array(uniqueCoords.length + 1);

  function sum(index) {
    let result = 0;
    while (index > 0) {
      result += bit[index];
      index -= index & -index;
    }
    return result;
  }

  function add(index) {
    while (index < bit.length) {
      bit[index]++;
      index += index & -index;
    }
  }

  let answer = 0;
  let inserted = 0;

  for (let i = 0; i < n;) {
    let j = i + 1;
    while (j < n && lines[j].y1 === lines[i].y1) j++;

    for (let k = i; k < j; k++) {
      const r = rank.get(lines[k].y2.toString());
      answer += inserted - sum(r - 1);
    }

    const count = j - i;
    answer += count * (count - 1) / 2;

    for (let k = i; k < j; k++) {
      add(rank.get(lines[k].y2.toString()));
    }

    inserted += count;
    i = j;
  }

  console.log(answer);
}
